CREATE OR REPLACE FUNCTION public.finance_campaign_metrics(_from date,_to date) RETURNS TABLE(campaign_id uuid,campaign_name text,account_id uuid,delivered bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.id,c.name,o.account_id,count(DISTINCT e.message_id) FROM public.campaigns c LEFT JOIN public.sponsor_offers o ON o.id=c.sponsor_offer_id LEFT JOIN public.delivery_events e ON e.campaign_id=c.id AND e.event_type='delivered' AND e.occurred_at>=(_from::timestamp AT TIME ZONE 'UTC') AND e.occurred_at<((_to+1)::timestamp AT TIME ZONE 'UTC') WHERE public.has_role(auth.uid(),'superadmin') OR EXISTS(SELECT 1 FROM public.worker_tasks WHERE user_id=auth.uid() AND status='active' AND allowed_paths @> ARRAY['/dashboard/finance']) GROUP BY c.id,c.name,o.account_id $$;
REVOKE ALL ON FUNCTION public.finance_campaign_metrics(date,date) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.finance_campaign_metrics(date,date) TO authenticated,service_role;